using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using OrderService.Services;namespace OrderService.Controllers;public record CreateOrderRequest(List<Line>Items);[ApiController][Authorize][Route("api/orders")]public class OrdersController(IOrder s):ControllerBase{Guid U=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpPost]public async Task<IActionResult>Create(CreateOrderRequest r,CancellationToken c)=>Ok(await s.Create(U,r.Items,c));[HttpGet("my-orders")]public async Task<IActionResult>Mine(int pageNumber=1,int pageSize=10,CancellationToken c=default)=>Ok(await s.Mine(U,Math.Max(1,pageNumber),Math.Clamp(pageSize,1,100),c));[HttpGet("{id:guid}")]public async Task<IActionResult>Get(Guid id,CancellationToken c)=>((await s.Get(id,U,User.IsInRole("ADMIN"),c)) is var o&&o!=null)?Ok(o):NotFound();[HttpPatch("{id:guid}/cancel")]public async Task<IActionResult>Cancel(Guid id,CancellationToken c)=>((await s.Cancel(id,U,User.IsInRole("ADMIN"),c)) is var o&&o!=null)?Ok(o):NotFound();}